use serde_json::json;
use std::{fs,path::Path};
fn tree(src:&Path,dst:&Path){fs::create_dir_all(dst).unwrap();for e in fs::read_dir(src).unwrap(){let p=e.unwrap().path();if p.file_name().unwrap()=="target"{continue}let q=dst.join(p.file_name().unwrap());if p.is_dir(){tree(&p,&q)}else{fs::copy(&p,q).unwrap();}}}
fn main(){let root=Path::new("/tmp/zopro-retained-deque-buffers");assert!(!root.join("overlay-v2").exists());
tree(&root.join("overlay"),&root.join("overlay-v2"));
let vendor=root.join("overlay-v2/vendor/crossbeam-deque-0.8.8");let p=vendor.join("src/deque.rs");let original=fs::read_to_string(&p).unwrap();assert_eq!(original.matches("use std::sync::Arc;\n").count(),1);let repaired=original.replace("use std::sync::Arc;\n","use std::sync::Arc;\n#[cfg(zopro_retained_deque_buffers)]\nuse std::vec::Vec;\n").replace("        eprintln!(\"ZOPRO_DEQUE_BUFFER", "        std::eprintln!(\"ZOPRO_DEQUE_BUFFER");fs::write(&p,repaired).unwrap();
let p=vendor.join("src/deque/retained_tests.rs");let original=fs::read_to_string(&p).unwrap();fs::write(&p,original.replacen("use super::*;", "use super::*;\nuse std::vec;",1)).unwrap();
let p=vendor.join("Cargo.toml");let original=fs::read_to_string(&p).unwrap();fs::write(&p,original.replacen("    \"cfg(crossbeam_loom)\",", "    \"cfg(crossbeam_loom)\",\n    \"cfg(zopro_retained_deque_buffers)\",\n    \"cfg(zopro_deque_trace)\",",1)).unwrap();
tree(&root.join("model"),&root.join("model-v2"));let p=root.join("model-v2/src/lib.rs");let original=fs::read_to_string(&p).unwrap();let repaired=original.replace("            if (*p).live.load(Ordering::SeqCst) { (*p).reclaim(&self.freed); }", "            let current = &*p;\n            if current.live.load(Ordering::SeqCst) { current.reclaim(&self.freed); }");assert_ne!(original,repaired);fs::write(p,repaired).unwrap();
tree(&root.join("upstream"),&root.join("upstream-v2"));let p=root.join("upstream-v2/rayon-core-1.13.0/Cargo.toml");let original=fs::read_to_string(&p).unwrap();fs::write(p,original.replace("../../candidate/vendor/","../../candidate-v2/vendor/")).unwrap();
fs::write(root.join("failure-v1.json"),format!("{}\n",serde_json::to_string_pretty(&json!({"native":"Stopped at first deque-off compile: Crossbeam is no_std with explicit std imports; private code lacked Vec import. No tests or SDK timing ran.","model":"Compiler rejected implicit autoref through a raw pointer to a Loom Arc; make the intended shared borrow explicit. No model ran.","repair":"Separate overlay/candidate/upstream/model v2 snapshots. Import Vec and test vec macro, qualify trace std::eprintln, register private cfg names, explicit model borrow. Queue lifetime/order/extraction logic unchanged. Preserve all v1 sources/receipts.","timing_before_repair":false})).unwrap())).unwrap();
println!("V1 compilation failures retained; separate v2 import/borrow fixes, unchanged runtime algorithm");}
